CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY "Own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, full_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', '')); RETURN NEW; END; $$;
CREATE TRIGGER create_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own role read" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('NX-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), product_id text NOT NULL, product_name text NOT NULL, customer_name text NOT NULL, email text NOT NULL, phone text NOT NULL, quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 5), unit_price numeric(10,2) NOT NULL, status text NOT NULL DEFAULT 'reservado' CHECK(status IN ('reservado','contatado','vendido','cancelado')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.reservations TO authenticated;
GRANT ALL ON public.reservations TO service_role;
ALTER TABLE public.reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin reservations read" ON public.reservations FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin reservations update" ON public.reservations FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE INDEX reservations_created_idx ON public.reservations(created_at DESC);
CREATE FUNCTION public.reserve_product(p_product_id text, p_name text, p_email text, p_phone text, p_quantity integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_name text; v_price numeric; v_code text;
BEGIN
IF p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 5 AND 100 OR trim(p_name) !~ '[[:space:]]' THEN RAISE EXCEPTION 'Informe seu nome completo'; END IF;
IF p_email IS NULL OR length(p_email)>255 OR trim(p_email) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]{2,}$' THEN RAISE EXCEPTION 'E-mail inválido'; END IF;
IF p_phone IS NULL OR length(p_phone)>30 OR length(regexp_replace(p_phone,'[^0-9]','','g')) NOT BETWEEN 10 AND 11 THEN RAISE EXCEPTION 'Telefone inválido'; END IF;
IF p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Quantidade inválida'; END IF;
CASE p_product_id WHEN '01' THEN v_name := 'Modu-Desk'; v_price := 1199; WHEN '02' THEN v_name := 'Spider Flex'; v_price := 299; WHEN '03' THEN v_name := 'Tênis McFly'; v_price := 699; ELSE RAISE EXCEPTION 'Produto inválido'; END CASE;
PERFORM pg_advisory_xact_lock(hashtext(lower(trim(p_email))));
IF (SELECT count(*) FROM public.reservations WHERE email = lower(trim(p_email)) AND created_at > now()-interval '1 hour') >= 5 THEN RAISE EXCEPTION 'Limite de reservas atingido. Tente mais tarde'; END IF;
INSERT INTO public.reservations(product_id,product_name,customer_name,email,phone,quantity,unit_price) VALUES(p_product_id,v_name,trim(p_name),lower(trim(p_email)),p_phone,p_quantity,v_price) RETURNING code INTO v_code;
RETURN v_code;
END; $$;
REVOKE ALL ON FUNCTION public.reserve_product(text,text,text,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reserve_product(text,text,text,text,integer) TO anon, authenticated;
